// Characterization tests: pin the API as clients currently see it, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 10, pear: 25.5, gold: 150 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order with 201 and json content type', async () => {
  const res = await post({ items: [{ sku: 'apple', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const order = await res.json()
  assert.deepEqual(Object.keys(order).sort(), ['id', 'items', 'total'])
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order.items, [{ sku: 'apple', qty: 2 }])
  assert.equal(order.total, 20)
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums multiple items', async () => {
  const order = await (await post({ items: [{ sku: 'apple', qty: 1 }, { sku: 'pear', qty: 2 }] })).json()
  assert.equal(order.total, 61) // 61 total, no discount
})

test('total is floored', async () => {
  const order = await (await post({ items: [{ sku: 'pear', qty: 1 }] })).json()
  assert.equal(order.total, 25)
})

test('10% discount applies only when total is strictly above 100', async () => {
  assert.equal((await (await post({ items: [{ sku: 'apple', qty: 10 }] })).json()).total, 100)
  assert.equal((await (await post({ items: [{ sku: 'apple', qty: 11 }] })).json()).total, 99)
  assert.equal((await (await post({ items: [{ sku: 'gold', qty: 1 }] })).json()).total, 135)
})

test('discounted total is floored', async () => {
  // 25.5 * 5 = 127.5 -> 114.75 -> 114
  const order = await (await post({ items: [{ sku: 'pear', qty: 5 }] })).json()
  assert.equal(order.total, 114)
})

test('invalid bodies return 400 {error: "items required"}', async () => {
  for (const [body, raw] of [[{}], [{ items: [] }], [{ items: 'x' }], [null, 'not json'], [null, '']]) {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('unknown sku (no price) yields a null total', async () => {
  const res = await post({ items: [{ sku: 'nope', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'apple', qty: 3 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with {error: "not found"} (not 404)', async () => {
  const res = await fetch(`${base}/orders/999999`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods return 404 {error: "no route"}', async () => {
  for (const [method, path] of [['GET', '/'], ['GET', '/orders'], ['PUT', '/orders'], ['DELETE', '/orders/1'], ['GET', '/orders/1/x']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
